def excluded_corpus(relative):
    """Keep D001 export evidence and JSON lineage; bulk corpus arrays stay external."""
    if 'corpus' not in relative.parts:
        return False
    if relative.parts[:2] != ('D001', 'corpus'):
        return True
    return relative.suffix != '.json' and relative.parts[2:3] != ('track_run',)


